-- ข้อมูลต้นฉบับ+หมวดหมู่ : ปริมาณการขนส่งสินค้าทางเรือ (2565-2568 / 2022-2025)
-- แหล่งข้อมูล: datagov.mot.go.th (dataset_21_01_03)
-- จำนวน 956 แถว | รองรับ MySQL / MariaDB / PostgreSQL / SQLite
-- หมายเหตุ: ไฟล์เข้ารหัส UTF-8 (MySQL: SET NAMES utf8mb4)

DROP TABLE IF EXISTS shipping_original;

CREATE TABLE shipping_original (
    id            INTEGER        PRIMARY KEY,   -- ลำดับแถวตามไฟล์ต้นฉบับ
    year_be       SMALLINT       NOT NULL,      -- ปี พ.ศ.
    year_ce       SMALLINT       NOT NULL,      -- ปี ค.ศ.
    province_th   VARCHAR(100)   NOT NULL,      -- จังหวัด
    province_en   VARCHAR(100)   NOT NULL,      -- Area (EN)
    flow_th       VARCHAR(20)    NOT NULL,      -- ประเภท (ขาเข้า/ขาออก)
    flow_en       VARCHAR(20)    NOT NULL,      -- Processing (EN) (Arrival/Departure)
    good_th       VARCHAR(100)   NOT NULL,      -- สินค้าเดิม (23 รายการ)
    good_en       VARCHAR(100)   NOT NULL,      -- Original Good (EN)
    category_th   VARCHAR(100)   NOT NULL,      -- หมวดหมู่ใหม่ (7 หมวด)
    category_en   VARCHAR(100)   NOT NULL,      -- New Category (EN)
    weight_kg     DECIMAL(18,2)  NOT NULL       -- น้ำหนักรวม (กก.)
);











CREATE INDEX idx_shipping_year     ON shipping_original (year_ce);
CREATE INDEX idx_shipping_province ON shipping_original (province_en);
CREATE INDEX idx_shipping_category ON shipping_original (category_en);
